/*
** EPITECH PROJECT, 2025
** mp3player
** File description:
** one song of a group of the duplicates screen: which upload it is
** (generated by YouTube or not), its likeness with the reference, title
** and artists, duration, listening time, file, and listening to it
** (nothing counted, src/scene/pages/listen_bar.c)
*/

#include "mp3player.h"

static const sfColor gray = {180, 180, 180, 255};
static const sfColor green = {120, 220, 120, 255};
static const sfColor orange = {255, 160, 60, 255};

static void kind(app_t *app, dup_group_t const *group, int i, float y)
{
    song_t const *song = group->songs[i];
    char const *text = "Clip / autre upload";

    if (song->autogen)
        text = i == 0 ? "Auto-généré (conseillé)" : "Auto-généré";
    widget_text(app, text, (float [3]){130, y + 8, 20},
        song->autogen ? &green : &gray);
}

static void likeness(app_t *app, dup_group_t const *group, int i, float y)
{
    char line[48];
    sfColor const *color = &gray;
    int audio = group->audio[i];

    snprintf(line, sizeof(line), "son non comparé");
    if (audio >= 0)
        snprintf(line, sizeof(line), "son identique à %d %%", audio);
    if (audio >= 0)
        color = audio >= DUP_SURE ? &green : &orange;
    if (i == 0 && audio == 100) {
        snprintf(line, sizeof(line), "référence");
        color = &gray;
    }
    widget_text(app, line, (float [3]){130, y + 42, 20}, color);
}

static void texts(app_t *app, song_t *song, float y)
{
    char line[NAME_LEN * 2 + 8];
    char cut[48 + 4];
    char time[32];
    char listen[32];
    char file[36 + 4];

    snprintf(line, sizeof(line), "%s%s%s", song_title(song),
        song->artists ? " - " : "", song->artists ? song->artists : "");
    utf8_cut(cut, line, 48);
    widget_text(app, cut, (float [3]){420, y + 6, 22}, &sfWhite);
    format_time(time, sizeof(time), song->duration_ms > 0 ?
        song->duration_ms : 0);
    format_time(listen, sizeof(listen), song_total_listen(app->lib, song));
    utf8_cut(file, song->file ? song->file : "", 36);
    snprintf(line, sizeof(line), "%s   écouté %s   %s", time, listen, file);
    widget_text(app, line, (float [3]){420, y + 40, 18}, &gray);
}

/*
** returns 1 if a click was used here
*/
static int listen(app_t *app, song_t *song, float y)
{
    if (listen_button(app, song, (float [4]){1050, y + 8, 150, 44}))
        return 1;
    if (!listen_mine(app, song))
        return 0;
    if (listen_bar(app, (float [4]){420, y + 66, 610, 5}))
        return 1;
    listen_time(app, (float [3]){1050, y + 54, 18});
    return 0;
}

/*
** returns 1 if a click was used here
*/
int dup_row(app_t *app, dup_group_t const *group, int i, float y)
{
    kind(app, group, i, y);
    likeness(app, group, i, y);
    texts(app, group->songs[i], y);
    return listen(app, group->songs[i], y);
}
